def move_verified_emails(apps, schema_editor):
    AccountSecurity = apps.get_model("core", "AccountSecurity")
    ReaderProfile = apps.get_model("core", "ReaderProfile")
    app_label, model_name = settings.AUTH_USER_MODEL.split(".")
    User = apps.get_model(app_label, model_name)
    database = schema_editor.connection.alias

    for user in User.objects.using(database).iterator():
        AccountSecurity.objects.using(database).get_or_create(user_id=user.pk)

    for profile in ReaderProfile.objects.using(database).select_related("user").filter(email_verified=True).iterator():
        email = profile.user.email or ""
        if email:
            AccountSecurity.objects.using(database).filter(user_id=profile.user_id).update(
                verified_email=email,
                email_verified_at=timezone.now(),
            )


def restore_reader_email_flags(apps, schema_editor):
    AccountSecurity = apps.get_model("core", "AccountSecurity")
    ReaderProfile = apps.get_model("core", "ReaderProfile")
    database = schema_editor.connection.alias
    for profile in ReaderProfile.objects.using(database).select_related("user").iterator():
        try:
            security = AccountSecurity.objects.using(database).get(user_id=profile.user_id)
        except AccountSecurity.DoesNotExist:
            continue
        verified = bool(security.email_verified_at and security.verified_email == profile.user.email)
        ReaderProfile.objects.using(database).filter(pk=profile.pk).update(email_verified=verified)


